function policy(obs, params, mem) {
  var LO = [0.40, 0.15, -0.85, -0.90, -1.10, -1.10, -1.65, 0.45, -0.45, -350, -140, 15, 0, 15, 0, 0, 0, 0.80, -0.50, -0.80, -0.80, 0.05, 0, -0.60, -0.60, 0.20];
  var HI = [1.20, 0.95, 0.10, -0.08, -0.08, -0.08, -0.08, 0.88, 0.35, 350, 140, 350, 110, 350, 110, 800, 250, 1.18, 3.50, 1.40, 1.40, 1.50, 0.50, 0.90, 0.60, 1.80];
  var DF = [0.75, 0.50, -0.22, -0.30, -0.42, -0.25, -0.95, 0.68, -0.05, 110, 28, 130, 20, 130, 18, 180, 35, 1.05, 1.20, 0.35, 0.30, 0.45, 0.25, 0.25, 0.10, 0.90];

  var v = mem._v;
  if (!v) v = mem._v = [];
  var i, s, q, P = params, hasP = (P && typeof P.length === "number");
  for (i = 0; i < 26; i++) {
    q = hasP ? +P[i] : NaN;
    if (q !== q) q = DF[i];
    if (q < LO[i]) q = LO[i];
    if (q > HI[i]) q = HI[i];
    v[20 + i] = q;
  }
  for (i = 0; i < 20; i++) {
    q = +obs[i];
    if (q !== q || q > 1e6 || q < -1e6) q = 0;
    v[i] = q;
  }

  var tA = v[0], tS = v[1], vx = v[2], vy = v[3], hgt = v[4];
  var hipA = v[5], hipAv = v[6], knA = v[7], knAv = v[8], fA = v[9];
  var hipB = v[10], hipBv = v[11], knB = v[12], knBv = v[13], fB = v[14];
  var ah1 = v[15], ah2 = v[16], ah3 = v[17], ah4 = v[18], tt = v[19];

  var dt = 1 / 60;
  if (mem.ini === undefined) {
    mem.ini = 1;
    mem.ph = 0;
    mem.pt = tt;
    mem.fA = (fA > 0.5) ? 1 : 0;
    mem.fB = (fB > 0.5) ? 1 : 0;
    mem.h0a = hipA; mem.k0a = knA;
    mem.h0b = hipB; mem.k0b = knB;
    mem.hb = 0;
  } else {
    q = tt - mem.pt;
    if (q > 0 && q < 0.25) dt = q;
    mem.pt = tt;
  }

  // ---- gait oscillator with touchdown phase-lock ----
  var T = v[20], duty = v[27];
  var ph = mem.ph + dt / T;
  var sA = (fA > 0.5) ? 1 : 0, sB = (fB > 0.5) ? 1 : 0;
  var pr = v[42];
  if (pr > 0.001) {
    if (sA === 1 && mem.fA === 0) {
      q = ph - Math.floor(ph);
      if (q > 0.5) q -= 1;
      if (q > -0.35 && q < 0.35) ph -= pr * q;
    }
    if (sB === 1 && mem.fB === 0) {
      q = ph + 0.5;
      q = q - Math.floor(q);
      if (q > 0.5) q -= 1;
      if (q > -0.35 && q < 0.35) ph -= pr * q;
    }
  }
  ph = ph - Math.floor(ph);
  mem.ph = ph;
  mem.fA = sA;
  mem.fB = sB;

  // ---- terrain ahead ----
  var ob = ah1;
  if (ah2 * 0.9 > ob) ob = ah2 * 0.9;
  if (ah3 * 0.7 > ob) ob = ah3 * 0.7;
  if (ah4 * 0.5 > ob) ob = ah4 * 0.5;
  if (ob > 0.45) ob = 0.45;
  if (ob < -0.45) ob = -0.45;

  // ---- torso balance torque (N*m, added to both hip motors) ----
  var bal = v[29] * (tA - v[28]) + v[30] * tS;

  // ---- step placement bias from capture point ----
  var nomFx = 0.36 * Math.sin(tA + v[21]) + 0.42 * Math.sin(tA + v[21] + v[23]);
  var hh = hgt;
  if (hh < 0.4) hh = 0.4;
  if (hh > 1.5) hh = 1.5;
  var om = Math.sqrt(9.05 / (hh * 0.85));
  var hbias = v[38] * (vx / om - nomFx) + v[44] * (v[45] - vx);
  if (hbias > 0.35) hbias = 0.35;
  if (hbias < -0.35) hbias = -0.35;
  mem.hb = 0.8 * mem.hb + 0.2 * hbias;
  hbias = mem.hb;

  // ---- body height torque (N*m, added to both knee motors) ----
  var hTg = v[37] + v[43] * (ob > 0 ? ob : 0);
  var hTor = v[35] * (hTg - hgt) - v[36] * vy;

  // ---- key tables ----
  var KP = mem._kp;
  if (!KP) KP = mem._kp = [0, 0, 0, 0, 0];
  var KV = mem._kv;
  if (!KV) KV = mem._kv = [0, 0, 0, 0, 0];
  KP[0] = 0;
  KP[1] = 0.45 * duty;
  KP[2] = duty;
  KP[3] = duty + 0.5 * (1 - duty);
  KP[4] = 1;
  KV[0] = v[23]; KV[1] = v[24]; KV[2] = v[25]; KV[3] = v[26]; KV[4] = v[23];

  var ramp = tt / v[41];
  if (ramp > 1) ramp = 1;
  if (ramp < 0) ramp = 0;

  var out = [0, 0, 0, 0];
  for (var leg = 0; leg < 2; leg++) {
    var psi = ph + (leg ? 0.5 : 0);
    if (psi >= 1) psi -= 1;

    // swing weight 0..1
    var sw = 0;
    if (psi >= duty) {
      var uw = (psi - duty) / (1 - duty);
      if (uw > 0.88) {
        sw = (1 - uw) / 0.12;
        if (sw > 1) sw = 1;
        if (sw < 0) sw = 0;
      } else {
        sw = uw / 0.18;
        if (sw > 1) sw = 1;
      }
    }

    // hip keyframe interpolation (stance then swing)
    var p0, p1, w0, w1;
    if (psi < duty) { p0 = 0; p1 = duty; w0 = v[21]; w1 = v[22]; }
    else { p0 = duty; p1 = 1; w0 = v[22]; w1 = v[21]; }
    var u1 = (psi - p0) / (p1 - p0);
    if (u1 < 0) u1 = 0;
    if (u1 > 1) u1 = 1;
    var su1 = u1 * u1 * (3 - 2 * u1);
    var hipT = w0 + (w1 - w0) * (0.5 * u1 + 0.5 * su1);
    var hipR = (w1 - w0) * (0.5 + 3 * u1 * (1 - u1)) / ((p1 - p0) * T);

    // knee keyframe interpolation (4 segments)
    var kT = 0, kR = 0;
    for (s = 0; s < 4; s++) {
      if (psi < KP[s + 1] || s === 3) {
        var q0 = KP[s], q1 = KP[s + 1];
        var u2 = (psi - q0) / (q1 - q0);
        if (u2 < 0) u2 = 0;
        if (u2 > 1) u2 = 1;
        var su2 = u2 * u2 * (3 - 2 * u2);
        kT = KV[s] + (KV[s + 1] - KV[s]) * (0.5 * u2 + 0.5 * su2);
        kR = (KV[s + 1] - KV[s]) * (0.5 + 3 * u2 * (1 - u2)) / ((q1 - q0) * T);
        break;
      }
    }

    // obstacle clearance during swing + placement bias
    hipT += hbias + v[40] * ob * sw;
    kT += -v[39] * ob * sw;

    // soft start from the initial pose
    var hs = leg ? mem.h0b : mem.h0a;
    var ks = leg ? mem.k0b : mem.k0a;
    hipT = hs + (hipT - hs) * ramp;
    kT = ks + (kT - ks) * ramp;
    hipR *= ramp;
    kR *= ramp;

    if (hipT > 1.15) hipT = 1.15;
    if (hipT < -0.85) hipT = -0.85;
    if (kT > -0.10) kT = -0.10;
    if (kT < -1.65) kT = -1.65;

    var hc = leg ? hipB : hipA, hcv = leg ? hipBv : hipAv;
    var kc = leg ? knB : knA, kcv = leg ? knBv : knAv;

    var tH = v[31] * (hipT - hc) + v[32] * (hipR - hcv) + bal;
    var tK = v[33] * (kT - kc) + v[34] * (kR - kcv) + hTor * (1 - 0.5 * sw);

    var oH = tH / 164, oK = tK / 141;
    if (oH > 1) oH = 1;
    if (oH < -1) oH = -1;
    if (oK > 1) oK = 1;
    if (oK < -1) oK = -1;
    if (oH !== oH) oH = 0;
    if (oK !== oK) oK = 0;

    out[leg * 2] = oH;
    out[leg * 2 + 1] = oK;
  }
  return out;
}

function learn(lab) {
  var DF = [0.75, 0.50, -0.22, -0.30, -0.42, -0.25, -0.95, 0.68, -0.05, 110, 28, 130, 20, 130, 18, 180, 35, 1.05, 1.20, 0.35, 0.30, 0.45, 0.25, 0.25, 0.10, 0.90];
  var LO = [0.40, 0.15, -0.85, -0.90, -1.10, -1.10, -1.65, 0.45, -0.45, -350, -140, 15, 0, 15, 0, 0, 0, 0.80, -0.50, -0.80, -0.80, 0.05, 0, -0.60, -0.60, 0.20];
  var HI = [1.20, 0.95, 0.10, -0.08, -0.08, -0.08, -0.08, 0.88, 0.35, 350, 140, 350, 110, 350, 110, 800, 250, 1.18, 3.50, 1.40, 1.40, 1.50, 0.50, 0.90, 0.60, 1.80];
  var SG = [0.10, 0.12, 0.12, 0.11, 0.11, 0.11, 0.16, 0.06, 0.09, 60, 15, 55, 10, 55, 10, 90, 18, 0.05, 0.70, 0.28, 0.28, 0.22, 0.12, 0.22, 0.16, 0.26];
  var N = 26;

  var maxTrials = 1000;
  try { if (lab && typeof lab.trials === "number" && lab.trials > 0) maxTrials = Math.floor(lab.trials); } catch (e) {}
  if (!(maxTrials > 0)) maxTrials = 1000;
  if (maxTrials > 1000) maxTrials = 1000;

  var used = 0;
  var bestP = DF.slice(), bestF = -1e18;
  var t0 = 0;
  try { t0 = Date.now(); } catch (e) { t0 = 0; }

  function timeUp() {
    if (!t0) return false;
    try { return (Date.now() - t0) > 152000; } catch (e) { return true; }
  }
  function clampP(p) {
    for (var i = 0; i < N; i++) {
      var x = +p[i];
      if (x !== x) x = DF[i];
      if (x < LO[i]) x = LO[i];
      if (x > HI[i]) x = HI[i];
      p[i] = x;
    }
    return p;
  }
  function fitOf(r) {
    if (!r) return -1e9;
    var d = +r.distance;
    if (d !== d || d > 1e6 || d < -1e6) d = -10;
    var tm = +r.time;
    if (tm !== tm) tm = 0;
    var f = d;
    if (r.outcome === "finished") f += 2.5;
    f += 0.02 * (tm > 10 ? 10 : tm);
    return f;
  }
  function ev(p) {
    if (used >= maxTrials || timeUp()) return -1e18;
    try { if (lab && lab.trialsLeft && lab.trialsLeft() <= 0) return -1e18; } catch (e) {}
    used++;
    var r = null;
    try { r = lab.trial(p); } catch (e) { r = null; }
    var f = fitOf(r);
    if (f > bestF) { bestF = f; bestP = p.slice(); }
    return f;
  }
  function gauss() {
    var u = Math.random();
    if (u < 1e-9) u = 1e-9;
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.283185307 * Math.random());
  }

  // ---- sign-convention probes ----
  var pr0 = clampP(DF.slice());
  var pr1 = pr0.slice(); pr1[9] = -pr1[9]; pr1[10] = -pr1[10];
  var pr2 = pr0.slice(); var swp = pr2[1]; pr2[1] = pr2[2]; pr2[2] = swp;
  var pr3 = pr2.slice(); pr3[9] = -pr3[9]; pr3[10] = -pr3[10];
  ev(pr0); ev(pr1); ev(pr2); ev(pr3);

  var mean = bestP.slice();
  var std = SG.slice();
  var sigMul = (bestF < 2) ? 1.5 : 1.0;
  var stagnant = 0;

  // ---- cross-entropy search ----
  var pop = 44, elite = 11;
  while (used + 4 < maxTrials && !timeUp()) {
    var prevBest = bestF;
    var cand = [], fts = [];
    for (var i = 0; i < pop; i++) {
      if (used >= maxTrials || timeUp()) break;
      var p;
      if (i === 0) p = bestP.slice();
      else if (i === 1) p = mean.slice();
      else {
        p = new Array(N);
        for (var j = 0; j < N; j++) {
          var x = mean[j] + std[j] * sigMul * gauss();
          if (x < LO[j]) x = LO[j];
          if (x > HI[j]) x = HI[j];
          p[j] = x;
        }
      }
      var f = ev(p);
      cand.push(p);
      fts.push(f);
    }
    if (cand.length < 6) break;

    var idx = [];
    for (var i = 0; i < cand.length; i++) idx.push(i);
    idx.sort(function (a, b) { return fts[b] - fts[a]; });

    var nE = Math.min(elite, idx.length);
    var nMean = new Array(N), nStd = new Array(N);
    for (var j = 0; j < N; j++) {
      var s = 0, ss = 0;
      for (var k = 0; k < nE; k++) {
        var xv = cand[idx[k]][j];
        s += xv; ss += xv * xv;
      }
      var m = s / nE;
      var vv = ss / nE - m * m;
      if (vv < 0) vv = 0;
      nMean[j] = 0.55 * mean[j] + 0.45 * m;
      var sd = Math.sqrt(vv) * 1.25 + 0.04 * SG[j];
      if (sd < 0.10 * SG[j]) sd = 0.10 * SG[j];
      if (sd > 1.25 * SG[j]) sd = 1.25 * SG[j];
      nStd[j] = sd;
    }
    mean = clampP(nMean);
    std = nStd;

    if (bestF > prevBest + 1e-9) {
      stagnant = 0;
      if (sigMul > 0.65) sigMul *= 0.94;
    } else {
      stagnant++;
      if (stagnant >= 2) {
        stagnant = 0;
        if (sigMul < 1.8) sigMul *= 1.25;
      }
    }
  }

  // ---- local polish around the best ----
  while (used < maxTrials && !timeUp()) {
    var p2 = new Array(N);
    for (var j2 = 0; j2 < N; j2++) {
      var x2 = bestP[j2] + 0.30 * SG[j2] * gauss();
      if (x2 < LO[j2]) x2 = LO[j2];
      if (x2 > HI[j2]) x2 = HI[j2];
      p2[j2] = x2;
    }
    ev(p2);
  }

  return bestP;
}

function policy(obs, params, mem) {
  var i, q;
  var N = 15;
  var DF = [0.60, 0.52, 0.70, -0.45, -0.80, -0.35, -1.20, 0.15, 300, 40, 400, 350, 0.90, 3.5, 0.60];
  var LO = [0.30, 0.35, 0.10, -0.85, -1.30, -1.00, -1.65, -0.20, -500, -100, 30, 30, 0.55, 0.0, 0.0];
  var HI = [1.00, 0.70, 1.15, 0.15, -0.25, -0.08, -0.50, 0.40, 500, 100, 600, 600, 1.10, 8.0, 2.0];

  var P = mem._P;
  if (!P) P = mem._P = [];
  var hasP = (params && typeof params.length === "number");
  for (i = 0; i < N; i++) {
    q = hasP ? +params[i] : NaN;
    if (q !== q) q = DF[i];
    if (q < LO[i]) q = LO[i];
    if (q > HI[i]) q = HI[i];
    P[i] = q;
  }

  var v = mem._v;
  if (!v) v = mem._v = [];
  for (i = 0; i < 20; i++) {
    q = +obs[i];
    if (q !== q || q > 1e6 || q < -1e6) q = 0;
    v[i] = q;
  }

  var tA = v[0], tS = v[1], vx = v[2], vy = v[3], hgt = v[4];
  var hA = v[5], hAv = v[6], kA = v[7], kAv = v[8], fA = v[9];
  var hB = v[10], hBv = v[11], kB = v[12], kBv = v[13], fB = v[14];
  var ah1 = v[15], ah2 = v[16], ah3 = v[17], ah4 = v[18], tt = v[19];

  var dt = 1 / 60;
  if (mem.ini === undefined) {
    mem.ini = 1;
    mem.ph = 0;
    mem.pt = tt;
    mem.h0a = hA; mem.k0a = kA;
    mem.h0b = hB; mem.k0b = kB;
    mem.fA = 0; mem.fB = 0;
  } else {
    q = tt - mem.pt;
    if (q > 0 && q < 0.25) dt = q;
    mem.pt = tt;
  }

  var T = P[0], duty = P[1];
  var ph = mem.ph + dt / T;

  var sA = (fA > 0.5) ? 1 : 0, sB = (fB > 0.5) ? 1 : 0;
  if (sA === 1 && mem.fA === 0) {
    q = ph - Math.floor(ph);
    if (q > 0.5) q -= 1;
    if (q > -0.3 && q < 0.3) ph -= 0.25 * q;
  }
  if (sB === 1 && mem.fB === 0) {
    q = ph + 0.5 - Math.floor(ph + 0.5);
    if (q > 0.5) q -= 1;
    if (q > -0.3 && q < 0.3) ph -= 0.25 * q;
  }
  mem.fA = sA; mem.fB = sB;
  ph = ph - Math.floor(ph);
  mem.ph = ph;

  var ob = ah1;
  if (ah2 * 0.85 > ob) ob = ah2 * 0.85;
  if (ah3 * 0.65 > ob) ob = ah3 * 0.65;
  if (ah4 * 0.45 > ob) ob = ah4 * 0.45;
  if (ob > 0.35) ob = 0.35;
  if (ob < -0.35) ob = -0.35;

  var bal = P[8] * (P[7] - tA) + P[9] * (-tS);
  if (bal > 60) bal = 60;
  if (bal < -60) bal = -60;

  var hCorr = P[13] * ((P[12] - hgt) - 0.2 * vy);
  if (hCorr > 0.8) hCorr = 0.8;
  if (hCorr < -0.8) hCorr = -0.8;

  var hEff = (hgt > 0.3) ? hgt : 0.3;
  var omega = Math.sqrt(9.05 / hEff);
  var cp = vx / omega;
  var sBias = P[14] * cp;
  if (sBias > 0.3) sBias = 0.3;
  if (sBias < -0.3) sBias = -0.3;

  var ramp = tt / 1.0;
  if (ramp > 1) ramp = 1;
  if (ramp < 0) ramp = 0;

  var hipF = P[2], hipBk = P[3];
  var knSt = P[4], knPo = P[5], knSw = P[6];
  var kdH = P[10] * 0.07, kdK = P[11] * 0.07;

  var out = [0, 0, 0, 0];
  for (var leg = 0; leg < 2; leg++) {
    var psi = ph + (leg ? 0.5 : 0);
    if (psi >= 1) psi -= 1;

    var hipT, hipV, kneeT, kneeV;

    if (psi < duty) {
      var u = psi / duty;
      if (u > 1) u = 1;
      var bu = 0.5 * u + 0.5 * u * u * (3 - 2 * u);
      var bvu = 0.5 + 3 * u - 3 * u * u;
      hipT = hipF + (hipBk - hipF) * bu;
      hipV = (hipBk - hipF) * bvu / (duty * T);

      var kEnd = duty * 0.75;
      if (psi < kEnd) {
        kneeT = knSt; kneeV = 0;
      } else {
        var v2 = (psi - kEnd) / (duty - kEnd);
        if (v2 > 1) v2 = 1; if (v2 < 0) v2 = 0;
        var bu2 = 0.5 * v2 + 0.5 * v2 * v2 * (3 - 2 * v2);
        var bvu2 = 0.5 + 3 * v2 - 3 * v2 * v2;
        kneeT = knSt + (knPo - knSt) * bu2;
        kneeV = (knPo - knSt) * bvu2 / ((duty - kEnd) * T);
      }
    } else {
      var u = (psi - duty) / (1 - duty);
      if (u > 1) u = 1; if (u < 0) u = 0;
      var bu = 0.5 * u + 0.5 * u * u * (3 - 2 * u);
      var bvu = 0.5 + 3 * u - 3 * u * u;
      hipT = hipBk + (hipF - hipBk) * bu;
      hipV = (hipF - hipBk) * bvu / ((1 - duty) * T);

      var swDur = 1 - duty;
      var midSw = duty + swDur * 0.40;
      if (psi < midSw) {
        var v2 = (psi - duty) / (midSw - duty);
        if (v2 > 1) v2 = 1; if (v2 < 0) v2 = 0;
        var bu2 = 0.5 * v2 + 0.5 * v2 * v2 * (3 - 2 * v2);
        var bvu2 = 0.5 + 3 * v2 - 3 * v2 * v2;
        kneeT = knPo + (knSw - knPo) * bu2;
        kneeV = (knSw - knPo) * bvu2 / ((midSw - duty) * T);
      } else {
        var v2 = (psi - midSw) / (1 - midSw);
        if (v2 > 1) v2 = 1; if (v2 < 0) v2 = 0;
        var bu2 = 0.5 * v2 + 0.5 * v2 * v2 * (3 - 2 * v2);
        var bvu2 = 0.5 + 3 * v2 - 3 * v2 * v2;
        kneeT = knSw + (knSt - knSw) * bu2;
        kneeV = (knSt - knSw) * bvu2 / ((1 - midSw) * T);
      }
    }

    var sw = 0;
    if (psi > duty) {
      var uw = (psi - duty) / (1 - duty);
      sw = 4 * uw * (1 - uw);
      if (sw > 1) sw = 1;
      if (sw < 0) sw = 0;
    }
    if (sw > 0) {
      hipT += 0.35 * ob * sw;
      kneeT -= 0.50 * ob * sw;
    }

    if (psi >= duty) hipT += sBias;
    kneeT += hCorr * (psi < duty ? 1.0 : 0.3);

    if (hipT > 1.15) hipT = 1.15;
    if (hipT < -0.85) hipT = -0.85;
    if (kneeT > -0.08) kneeT = -0.08;
    if (kneeT < -1.65) kneeT = -1.65;

    var hs = leg ? mem.h0b : mem.h0a;
    var ks = leg ? mem.k0b : mem.k0a;
    hipT = hs + (hipT - hs) * ramp;
    kneeT = ks + (kneeT - ks) * ramp;
    hipV *= ramp; kneeV *= ramp;

    var hc = leg ? hB : hA, hcv = leg ? hBv : hAv;
