  ka: -0.9042425092533855, km: -1.1233508693682062, kph: 1.824466171215359,
  pb: 2.9140795157815234, kp: 4.429756361151736, kd: 0.05179211524993802,
  kb: -0.5464432476269234, bs: 0.025986409485773132, hk: 0.0666006417876901
};

function clamp(x, lo, hi) { return x < lo ? lo : (x > hi ? hi : x); }

function shaped(phi, sh) {
  if (sh === undefined || sh === null) return Math.sin(phi);
  const g = clamp(sh, 0.1, 50);
  return Math.tanh(g * Math.sin(phi)) / Math.tanh(g);
}

function policy(obs, params, mem) {
  const p = params || SEED;
  for (let i = 0; i < obs.length; i++) {
    if (!isFinite(obs[i])) return [0, 0, 0, 0];
  }
  const t = obs[19];
  const torsoAngle = obs[0], torsoSpin = obs[1];
  const bal = (p.kb || 0) * torsoAngle + (p.bs || 0) * torsoSpin;
  const w = 2 * Math.PI * p.f * t;

  const ahead = Math.max(obs[15], obs[16], 0.7 * obs[17]);
  const boost = (p.hk || 0) * clamp(ahead / 0.25, 0, 1);

  function drive(phase, hipAng, hipSpd, kneeAng, kneeSpd) {
    const hipT = clamp(p.hm + p.ha * shaped(phase, p.sh) + bal, -0.9, 1.2);
    const kneeT = clamp(
      p.km + p.ka * (1 - Math.cos(phase + p.kph)) / 2 - boost,
      -1.7, -0.05
    );
    const uh = clamp(p.kp * (hipT - hipAng) - p.kd * hipSpd, -1, 1);
    const uk = clamp(p.kp * (kneeT - kneeAng) - p.kd * kneeSpd, -1, 1);
    return [uh, uk];
  }

  const A = drive(w, obs[5], obs[6], obs[7], obs[8]);
  const B = drive(w + p.pb, obs[10], obs[11], obs[12], obs[13]);
  return [A[0], A[1], B[0], B[1]];
}

function learn(lab) {
  const hasDate = typeof Date !== 'undefined';
  const t0 = hasDate ? Date.now() : 0;
  const timeUp = () => hasDate && (Date.now() - t0) > 150000;
  const left = () => (lab && lab.trialsLeft ? Number(lab.trialsLeft()) : 1000);

  const toParams = (x) => {
    const p = {};
    KEYS.forEach((k, i) => {
      const [lo, hi] = RANGES[k];
      p[k] = lo + clamp(x[i], 0, 1) * (hi - lo);
    });
    return p;
  };
  const fromParams = (p) => KEYS.map((k) => {
    const [lo, hi] = RANGES[k];
    const v = (p[k] === undefined) ? (lo + hi) / 2 : p[k];
    return clamp((v - lo) / (hi - lo), 0, 1);
  });
  const gauss = () => {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };

  let bestP = null, bestX = null, bestS = -Infinity;

  const evalP = (p) => {
    if (timeUp() || left() <= 0) return null;
    let r;
    try { r = lab.trial(p); } catch (e) { return -1000; }
    if (!r) return -1000;
    let s = Number(r.distance);
    if (!isFinite(s)) s = -1;
    if (r.outcome === 'fell') s -= 2;
    if (r.outcome === 'invalid' || r.outcome === 'error') s -= 100;
    if (s > bestS) {
      bestS = s;
      bestP = p;
      bestX = null; // filled by caller when x is known
    }
    return s;
  };

  const evalX = (x) => {
    if (timeUp() || left() <= 0) return null;
    const p = toParams(x);
    const before = bestS;
    const s = evalP(p);
    if (s === null) return null;
    if (bestS > before) bestX = x.slice();
    return s;
  };

  const n = KEYS.length;
  const shIdx = KEYS.indexOf('sh');

  // 0) Baseline: attempt-5 seed exactly (sine waveform, no sh key)
  evalP(SEED);
  const seedX = fromParams(SEED);
  if (!bestX) bestX = seedX.slice();

  // 1) Exploration: half uniform global, half near the seed with random sharpness
  for (let i = 0; i < 200; i++) {
    if (timeUp() || left() <= 0) break;
    let x;
    if (i % 2 === 0) {
      x = KEYS.map(() => Math.random());
    } else {
      x = seedX.map((v) => clamp(v + 0.15 * gauss(), 0, 1));
      x[shIdx] = Math.random();
    }
    evalX(x);
  }
  if (!bestX) bestX = seedX.slice();

  // 2) Restarting (1..lam)-style evolution strategy around the best point
  let mean = bestX.slice();
  let sigma = 0.08;
  let lam = 8;
  let genPrevBest = bestS;
  let stall = 0;

  while (!timeUp() && left() > 0) {
    const mu = Math.max(1, Math.floor(lam / 2));
    const pop = [];
    for (let k = 0; k < lam; k++) {
      if (timeUp() || left() <= 0) break;
      const x = mean.map((m) => clamp(m + sigma * gauss(), 0, 1));
      const s = evalX(x);
      if (s === null) break;
      pop.push({ x, s });
    }
    if (pop.length === 0) break;

    pop.sort((a, b) => b.s - a.s);
    const m2 = Math.min(mu, pop.length);
    const w = [];
    let wsum = 0;
    for (let i = 0; i < m2; i++) {
      w.push(Math.log(m2 + 0.5) - Math.log(i + 1));
      wsum += w[i];
    }
    const nm = new Array(n).fill(0);
    for (let i = 0; i < m2; i++) {
      for (let j = 0; j < n; j++) nm[j] += (w[i] / wsum) * pop[i].x[j];
    }
    mean = nm.map((v) => clamp(v, 0, 1));

    if (bestS > genPrevBest + 1e-9) {
      sigma = Math.min(0.3, sigma * 1.25);
      stall = 0;
    } else {
      sigma *= 0.92;
      stall++;
    }
    genPrevBest = bestS;

    if (sigma < 0.008 || stall >= 15) {
      lam = Math.min(32, lam * 2);
      stall = 0;
      if (Math.random() < 0.5 && bestX) {
        mean = bestX.slice();
        sigma = 0.08;
      } else {
        mean = KEYS.map(() => Math.random());
        sigma = 0.25;
      }
      genPrevBest = bestS;
    }
  }

  return bestP || SEED;
}

const RANGES = {
  f:   [0.8, 3.2],     // gait frequency (Hz)
  ha:  [0.1, 0.7],     // hip swing amplitude (rad)
  hm:  [-0.9, 0.9],    // hip mean angle (rad)
  ka:  [-1.2, 1.2],    // knee swing amplitude (rad)
  km:  [-1.5, -0.2],   // knee mean angle (rad)
  kph: [-3.14, 3.14],  // knee phase relative to hip (rad)
  pb:  [0.0, 6.28],    // leg B phase offset (rad)
  kp:  [1.0, 10.0],    // position gain
  kd:  [0.0, 1.0],     // damping gain
  kb:  [-3.0, 3.0],    // hip bias from torso lean
  bs:  [-0.5, 0.5],    // hip bias from torso spin
  sh:  [0.5, 10.0]     // hip waveform sharpness (tanh gain)
};
const KEYS = Object.keys(RANGES);
const HK = 0.5; // fixed hurdle/rising-ground knee boost (not searched)

// Attempt 6 seed (pure sine hip waveform, ~13.3 m per 10 s trial)
