function learn(lab) {
  const hasDate = typeof Date !== 'undefined';
  const t0 = hasDate ? Date.now() : 0;
  const timeUp = () => hasDate && (Date.now() - t0) > 150000;
  const left = () => (lab && lab.trialsLeft ? Number(lab.trialsLeft()) : 1000);

  const toParams = (x) => {
    const p = {};
    KEYS.forEach((k, i) => {
      const [lo, hi] = RANGES[k];
      p[k] = lo + clamp(x[i], 0, 1) * (hi - lo);
    });
    p.hk = HK;
    return p;
  };
  const fromParams = (p) => KEYS.map((k) => {
    const [lo, hi] = RANGES[k];
    let v;
    if (p[k] === undefined) v = (k === 'sh') ? 0.5 : (lo + hi) / 2;
    else v = p[k];
    return clamp((v - lo) / (hi - lo), 0, 1);
  });
  const gauss = () => {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };

  let bestP = null, bestS = -Infinity;

  // One trial. Falls inside the 10 s trial are penalised more heavily.
  const run = (p) => {
    if (timeUp() || left() <= 0) return null;
    p.hk = HK;
    let r;
    try { r = lab.trial(p); } catch (e) { return -1000; }
    if (!r) return -1000;
    let s = Number(r.distance);
    if (!isFinite(s)) s = -1;
    if (r.outcome === 'fell') s -= 5;
    if (r.outcome === 'invalid' || r.outcome === 'error') s -= 100;
    if (s > bestS) {
      bestS = s;
      bestP = Object.assign({}, p);
    }
    return s;
  };

  // Phase 0: seed
  run(Object.assign({}, SEED));

  // Phase 1: grid over frequency / amplitude / waveform sharpness.
  // Hip speed cap (~5.2 rad/s) means amplitude*frequency should stay near 0.8.
  const fGrid = [1.6, 2.0, 2.4, 2.8, 3.2];
  const haGrid = [0.25, 0.35, 0.45, 0.6];
  const shGrid = [null, 1, 3, 8];
  for (const f of fGrid) {
    for (const ha of haGrid) {
      for (const sh of shGrid) {
        if (timeUp() || left() <= 0) break;
        const p = Object.assign({}, SEED, { f: f, ha: ha });
        if (sh === null) delete p.sh; else p.sh = sh;
        run(p);
      }
    }
  }

  // Phase 2: restarting (mu, lambda)-style evolution strategy around best-so-far
  const n = KEYS.length;
  let mean = fromParams(bestP || SEED);
  let sigma = 0.1;
  let lam = 10;
  let genPrev = bestS;
  let stall = 0;

  while (!timeUp() && left() > 0) {
    const mu = Math.max(1, Math.floor(lam / 2));
    const pop = [];
    for (let k = 0; k < lam; k++) {
      if (timeUp() || left() <= 0) break;
      const x = mean.map((m) => clamp(m + sigma * gauss(), 0, 1));
      const s = run(toParams(x));
      if (s === null) break;
      pop.push({ x: x, s: s });
    }
    if (pop.length === 0) break;

    pop.sort((a, b) => b.s - a.s);
    const m2 = Math.min(mu, pop.length);
    const w = [];
    let wsum = 0;
    for (let i = 0; i < m2; i++) {
      w.push(Math.log(m2 + 0.5) - Math.log(i + 1));
      wsum += w[i];
    }
    const nm = new Array(n).fill(0);
    for (let i = 0; i < m2; i++) {
      for (let j = 0; j < n; j++) nm[j] += (w[i] / wsum) * pop[i].x[j];
    }
    mean = nm.map((v) => clamp(v, 0, 1));

    if (bestS > genPrev + 1e-9) {
      sigma = Math.min(0.3, sigma * 1.25);
      stall = 0;
    } else {
      sigma *= 0.92;
      stall++;
    }
    genPrev = bestS;

    if (sigma < 0.008 || stall >= 15) {
      lam = Math.min(40, lam * 2);
      stall = 0;
      if (Math.random() < 0.6 && bestP) {
        mean = fromParams(bestP);
        sigma = 0.08;
      } else {
        mean = KEYS.map(() => Math.random());
        sigma = 0.25;
      }
      genPrev = bestS;
    }
  }

  return bestP || SEED;
}

const RANGES = {
  f:   [0.8, 3.5],     // gait frequency (Hz)
  ha:  [0.1, 0.6],     // hip swing amplitude (rad)
  hm:  [-0.9, 0.9],    // hip mean angle (rad)
  ka:  [-1.2, 1.2],    // knee swing amplitude (rad)
  km:  [-1.5, -0.2],   // knee mean angle (rad)
  kph: [-3.14, 3.14],  // knee phase relative to hip (rad)
