  kp:  [1.0, 10.0],    // position gain
  kd:  [0.0, 1.0],     // damping gain
  kb:  [-3.0, 3.0],    // hip bias from torso lean
  bs:  [-0.5, 0.5],    // hip bias from torso spin
  hk:  [0.0, 1.0]      // extra knee flexion when ground/hurdle ahead rises
