function learn(lab) {
  const hasDate = typeof Date !== 'undefined';
  const t0 = hasDate ? Date.now() : 0;
  const timeUp = () => hasDate && (Date.now() - t0) > 150000;
  const left = () => (lab && lab.trialsLeft ? Number(lab.trialsLeft()) : 1000);

  const toP = (x) => {
    const p = {};
    KEYS.forEach((k, i) => {
      const [lo, hi] = RANGES[k];
      p[k] = lo + clamp(x[i], 0, 1) * (hi - lo);
    });
    return p;
  };
  const fromP = (p) => KEYS.map((k) => {
    const [lo, hi] = RANGES[k];
    const v = (p[k] === undefined) ? (lo + hi) / 2 : p[k];
    return clamp((v - lo) / (hi - lo), 0, 1);
  });
  const gauss = () => {
    let u = 0, v = 0;
    while (u === 0) u = Math.random();
    v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };

  let bestP = null, bestS = -Infinity;

  const run = (p) => {
    if (timeUp() || left() <= 0) return null;
    let r;
    try { r = lab.trial(p); } catch (e) { return -1000; }
    if (!r) return -1000;
    let s = Number(r.distance);
    if (!isFinite(s)) s = -1;
    if (r.outcome === 'fell') s -= 2;
    if (r.outcome === 'invalid' || r.outcome === 'error') s -= 100;
    if (s > bestS) {
      bestS = s;
      bestP = Object.assign({}, p);
    }
    return s;
  };

  // Phase 0: seed and two hurdle-boost variants (hurdle boost is otherwise untested)
  run(Object.assign({}, SEED));
  run(Object.assign({}, SEED, { hk: 0.3 }));
  run(Object.assign({}, SEED, { hk: 0.6 }));

  let bestX = fromP(bestP || SEED);

  // Phase 1: (1+lambda) local search, only accepting strict trial improvements
  let sigma = 0.06;
  const lam = 8;
  while (!timeUp() && left() > 0) {
    let genImproved = false;
    for (let k = 0; k < lam; k++) {
      if (timeUp() || left() <= 0) break;
      const x = bestX.map((m) => clamp(m + sigma * gauss(), 0, 1));
      const before = bestS;
      const s = run(toP(x));
      if (s === null) break;
      if (bestS > before) {
        bestX = x.slice();
        genImproved = true;
      }
    }
    if (genImproved) {
      sigma = Math.min(0.2, sigma * 1.3);
    } else {
      sigma = Math.max(0.01, sigma * 0.9);
    }
  }

  return bestP || SEED;
}
